    url: {
      fontSize: '14px',
      fontWeight: '500',
      color: '#1a73e8',
      textDecoration: 'none',
      ':hover': {
        textDecoration: 'underline'
      }
    },
    contentContainer: {
      maxHeight: '300px',
      overflow: 'auto',
      padding: '8px',
      backgroundColor: '#f9f9f9',
      borderRadius: '4px'
    },
    content: {
