    imagesGrid: {
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fill, minmax(120px, 1fr))',
      gap: '8px'
    },
    image: {
      width: '100%',
      height: '100px',
      objectFit: 'cover',
      borderRadius: '4px'
    },
    failedHeader: {
      fontSize: '16px',
