      fontSize: '12px',
      color: '#70757a',
      textAlign: 'right',
      marginTop: '8px'
    },
    expandButton: {
      backgroundColor: '#f1f3f4',
      border: 'none',
      borderRadius: '4px',
      padding: '4px 8px',
      fontSize: '12px',
      cursor: 'pointer',
      color: '#1a73e8'
    }
  };

  // State for tracking expanded content
  const [expandedUrls, setExpandedUrls] = React.useState({});

  const toggleExpand = (url) => {
    setExpandedUrls(prev => ({
      ...prev,
      [url]: !prev[url]
    }));
  };

  return React.createElement('div', { style: styles.container },
    React.createElement('div', { style: styles.header },
      React.createElement('h2', null, 'Extracted Content'),
      React.createElement('span', { style: styles.responseTime }, `Response time: ${data.response_time}s`)
