            React.createElement('div', { style: styles.urlHeader },
              React.createElement('a', { 
                href: result.url,
                target: '_blank',
                rel: 'noopener noreferrer',
                style: styles.url
              }, result.url),
              React.createElement('button', {
                onClick: () => toggleExpand(result.url),
                style: styles.expandButton
              }, expandedUrls[result.url] ? 'Collapse' : 'Expand')
            ),
            React.createElement('div', { style: styles.contentContainer },
              React.createElement('div', { style: styles.content }, 
                expandedUrls[result.url] ? result.raw_content : truncateText(result.raw_content)
              )
            ),
            result.images && result.images.length > 0 && React.createElement('div', null,
              React.createElement('h4', { style: styles.imagesHeading }, 'Images:'),
